import java.util.*; import java.io.*; public class Solution { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String[] firstLine = br.readLine().split(" "); int n = Integer.parseInt(firstLine[0]); int k = Integer.parseInt(firstLine[1]); String[] secondLine = br.readLine().split(" "); int[] arr = new int[n]; Set<Integer> set = new HashSet<>(); for (int i = 0; i < n; i++) { arr[i] = Integer.parseInt(secondLine[i]); set.add(arr[i]); } int count = 0; for (int num : arr) { if (set.contains(num + k)) { count++; } } System.out.println(count); } }